(window.ArduinoSketches=window.ArduinoSketches||{})["b1_02_signal_hardcoded"]={"ok":true,"flash":1076,"ram":9,"program":"","name":"b1_02_signal_hardcoded","source":"// ==================================================================\n//   BAND 1, PART 6  -  THREE LIGHTS, WRITTEN THE LONG WAY\n//\n//   WHAT IT DOES\n//     Runs a road crossing sequence on three LEDs:\n//       red alone (5 s), red and yellow (1.5 s),\n//       green alone (5 s), yellow alone (1.5 s), then repeats.\n//\n//   WIRING\n//     Red    LED long leg f5,  short leg f6.  Resistor j5 to j3.  Wire h3 to pin 9.\n//     Yellow LED long leg f10, short leg f11. Resistor j10 to j8. Wire h8 to pin 8.\n//     Green  LED long leg f15, short leg f16. Resistor j15 to j13. Wire h13 to pin 7.\n//     Wire from j6, j11 and j16 each to the minus rail.\n//     ONE wire from the minus rail to a GND pin.\n//\n//   NOTICE\n//     Each of the four blocks says what ALL THREE lights are doing,\n//     even the ones that should be off. That is on purpose.\n//     Band 1 Part 7d explains why.\n// ==================================================================\n\nvoid setup() {\n  pinMode(9, OUTPUT);\n  pinMode(8, OUTPUT);\n  pinMode(7, OUTPUT);\n}\n\nvoid loop() {\n  digitalWrite(9, HIGH);\n  digitalWrite(8, LOW);\n  digitalWrite(7, LOW);\n  delay(5000);\n\n  digitalWrite(9, HIGH);\n  digitalWrite(8, HIGH);\n  digitalWrite(7, LOW);\n  delay(1500);\n\n  digitalWrite(9, LOW);\n  digitalWrite(8, LOW);\n  digitalWrite(7, HIGH);\n  delay(5000);\n\n  digitalWrite(9, LOW);\n  digitalWrite(8, HIGH);\n  digitalWrite(7, LOW);\n  delay(1500);\n}\n","compiler":"arduino-cli 1.5.1, arduino:avr:uno"};
